INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533465-pete202', 'stk-s3d_79', 'PETE 202', 'info', '{"desc": "TERM 211 (AZAD ) : v\n\nبسم الله …\n\nنبذة :\n\n-الماده متوسطه الصعوبه ( بالنسبه لي ) لكنها تحتاج مذاكره باستمرار لان الشباتر تبني ع اللي قبلها .\n\n-صعوبه الماده تكمن في انه مافي مصادر للمذاكره الا السلايدات والكتاب والدكتور ، على عكس اللي تعودنا عليه في مواد الفرشمن .\n- في ٢١١ الماده كانت كوردينيتد ، فلذلك المياجر والفاينل كانت كومون .\n\nطريقة المذاكرة :\n\n( بالنسبه لي ) كنت اكتب نوتات مع الدكتور واحاول افهم معاه ، بعدها اذا رجعت الغرفه ابدا الخص من الكتاب واحل الامثله اللي فيه بنفسي ، ( الامثله اللي موجوده في السلايدات ) ، طبعا الطريقه هذي تنفع للشباتر (١-٨) ، (١٠- ١٢) بتكون مواضيع داخله في البتروليوم وبتكون مواضيع من برا الكتاب .\n\nالكويزات :\n\n-كل دكتور يسوي كويزات لطلابه .\n\n- دايما وفي كل المواد ذاكر للكويزات كانك تذاكر للميجر ، لانك لو غلطت في الكويزات تقدر تصحح غلطك وتتفاداه قبل الميجر .\n\nالمياجر :\n\nالماده فيها ميجرين من ٢٠ (WRITTEN) ، الميجر يتكون من خمسه اسئلة ويكون تحته عدة فقرات ، دايما السؤال الاول يكون سؤال كونسبت ، والاربع اسئلة الباقية تكون مسائل .\n\nالبروجكت :\n\nالترم هذا كان هانداوت عن ( Natural Gas System ) واعطانا اسئلة عليه ، وبرضو مسألة تحتاج اننا نستخدم الاكسل عشان نحلها.\n\nالفاينل :\nعليه ٢٥ ويكون مشابه للمياجر ، وبيكون شامل للمنهج .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pete-202-phase-behavior/182919/2", "user": "S3D_79", "ts": 1642173916000, "tid": 182919, "pn": 2}}', 1642173916000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-pete202', 'stk-guest', 'PETE 202', 'doc', '{"docs": [{"id": "stk-dr-f98484", "n": "Dr. Abdullah Al-Sultan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Pete202-181\n\nالتحضير زي ماقالوا الشباب يدقق.\nالشرح عادي جدا.\nالكويزات كلها سهله مافيه تركات ولا شي نسخ لصق من السلايدز او الكتاب.\nالهوموركات مالها علاقه بالمنهج بس مفيده ويجيب منها في الميجر.\nالميجر الاول كان صعب جدا كان الافرج ٥٠ بس تساهله في التصحيح وبعدين عطانا ميجر ثاني وميجر ثالث واخذ درجة افضل ميجرين.\nتصحيحه افضل تصحيح ممكن تشوفه في الجامعه.\nالدكتور من اطيب الدكاتره اللي شفتهم حتى انه يوم شافنا مكسورين بعد الميجر الاول قال ابشروا بالخير بنحذفه لكم.\nوزود على كذا تصحيحه طول السمستر كان عسسسل.\nالفاينل كان صعب بس زي ماذكرت زبطنا في التصحيح.\nاذا شفته في الرجسترار سجل على طول ولا تفكر.\nنهاية السمستر زاد كل واحد فينا قريد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522325-pete202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-al-sultan/98484/10", "user": "Guest", "ts": 1590334689000, "tid": 98484, "pn": 10}}]}', 1590334689000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
